import React from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";

const ProfilePage = () => {
    const { user, logout } = useAuth();
    const navigate = useNavigate();

    const handleLogout = async () => {
        try {
            await logout();
            navigate("/login");
        } catch (error) {
            console.error("Logout failed:", error);
        }
    };

    return (
        <div style={{ maxWidth: 600, margin: "50px auto", padding: 20, backgroundColor: "#f5f7fa", borderRadius: 12 }}>
            <h1>Profilul Meu</h1>
            <p><strong>Email:</strong> {user?.email}</p>

            <div style={{ marginTop: 30 }}>
                <button style={buttonStyle} onClick={() => alert("Funcție Edit Profile nu este implementată încă")}>
                    Editare Profil
                </button>
                <button style={buttonStyle} onClick={() => alert("Funcție Setări nu este implementată încă")}>
                    Setări Cont
                </button>
                <button
                    style={{ ...buttonStyle, backgroundColor: "#dc3545", marginTop: 20 }}
                    onClick={handleLogout}
                >
                    Deconectare
                </button>
            </div>
        </div>
    );
};

const buttonStyle = {
    padding: "12px 20px",
    marginRight: 15,
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: 8,
    cursor: "pointer",
    fontSize: 16,
};

export default ProfilePage;
